#[derive(Debug, Subcommand)]
enum ArtifactCommand {
    /// Validate a candidate spec JSON file, or `-` for standard input.
    Validate { candidate: String },
    /// Validate and atomically persist a candidate spec JSON file.
    Persist {
        candidate: String,
        #[arg(long, default_value = ".")]
        workspace: String,
    },
    /// Revalidate and retrieve a canonical spec by ID.
    Get {
        id: String,
        #[arg(long, default_value = ".")]
        workspace: String,
    },
    /// Report whether the requested canonical spec is absent, uncommitted, or clean.
    Status {
        id: String,
        #[arg(long, default_value = ".")]
        workspace: String,
    },
}

#[derive(Debug, Diagnostic, Error)]
enum CliError {
    #[diagnostic(code(wisp::cli::input))]
    #[error("could not read candidate: {0}")]
    Input(#[source] std::io::Error),
    #[diagnostic(code(wisp::cli::workspace_path))]
    #[error("workspace path is not valid UTF-8")]
    WorkspacePath,
    #[diagnostic(code(wisp::cli::unsafe_id))]
    #[error("artifact ID is invalid: {0}")]
    Id(#[source] wisp_model::ArtifactIdError),
    #[diagnostic(code(wisp::artifact))]
    #[error(transparent)]
    Artifact(#[from] ArtifactError),
    #[diagnostic(transparent)]
    #[error(transparent)]
    Validation(#[from] SpecValidationError),
}

fn main() -> ExitCode {
    let cli = Cli::parse();
    let format = cli.format;
    match run(cli) {
        Ok(value) => write_json(&value, ExitCode::SUCCESS),
        Err(error) => match format {
            OutputFormat::Json => write_json(&error_json(&error), ExitCode::from(1)),
            OutputFormat::Human => {
                eprintln!("{:?}", miette::Report::new(error));
                ExitCode::from(1)
            }
        },
    }
}

fn run(cli: Cli) -> Result<Value, CliError> {
    match cli.command {
        Command::Artifact { command } => match command {
            ArtifactCommand::Validate { candidate } => {
                let validated = validate_spec_json(&read_candidate(&candidate)?)?;
                Ok(json!({"status":"validated", "artifact_type":"spec@1", "id":validated.id}))
            }
            ArtifactCommand::Persist {
                candidate,
                workspace,
            } => {
                let receipt =
                    persist_spec(&workspace_path(workspace)?, &read_candidate(&candidate)?)?;
                Ok(serde_json::to_value(receipt).map_err(|error| {
                    CliError::Validation(SpecValidationError::SchemaDefinition {
                        message: error.to_string(),
                    })
                })?)
            }
            ArtifactCommand::Get { id, workspace } => {
                let id = ArtifactId::new(id).map_err(CliError::Id)?;
                Ok(
                    serde_json::to_value(get_spec(&workspace_path(workspace)?, &id)?).map_err(
                        |error| {
                            CliError::Validation(SpecValidationError::SchemaDefinition {
                                message: error.to_string(),
                            })
                        },
                    )?,
                )
            }
            ArtifactCommand::Status { id, workspace } => {
                let id = ArtifactId::new(id).map_err(CliError::Id)?;
                let workspace = workspace_path(workspace)?;
                match get_spec(&workspace, &id) {
                    Ok(record) => Ok(
                        json!({"status":record.state, "artifact_type":"spec@1", "id":id, "path":record.path}),
                    ),
                    Err(ArtifactError::Absent { .. }) => Ok(
                        json!({"status":"absent", "artifact_type":"spec@1", "id":id, "path":spec_relative_path(&id)}),
                    ),
                    Err(error) => Err(CliError::Artifact(error)),
                }
            }
        },
    }
}

fn workspace_path(value: String) -> Result<Utf8PathBuf, CliError> {
    Utf8PathBuf::from_path_buf(std::path::PathBuf::from(value)).map_err(|_| CliError::WorkspacePath)
}

fn read_candidate(candidate: &str) -> Result<Vec<u8>, CliError> {
    if candidate == "-" {
        let mut bytes = Vec::new();
        std::io::stdin()
            .read_to_end(&mut bytes)
            .map_err(CliError::Input)?;
        Ok(bytes)
    } else {
        fs::read(candidate).map_err(CliError::Input)
    }
}

fn error_json(error: &CliError) -> Value {
    let code = match error {
        CliError::Input(_) => "input_error",
        CliError::WorkspacePath => "workspace_path_error",
        CliError::Id(_) | CliError::Validation(SpecValidationError::UnsafeId { .. }) => "unsafe_id",
        CliError::Validation(SpecValidationError::InvalidJson { .. }) => "invalid_json",
        CliError::Validation(SpecValidationError::SchemaViolation { .. }) => "schema_violation",
        CliError::Validation(SpecValidationError::SchemaDefinition { .. }) => {
            "schema_definition_error"
        }
        CliError::Artifact(ArtifactError::Validation { .. }) => "validation_error",
        CliError::Artifact(ArtifactError::Absent { .. }) => "absent",
        CliError::Artifact(ArtifactError::Filesystem { .. }) => "filesystem_error",
        CliError::Artifact(ArtifactError::Serialization { .. }) => "serialization_error",
    };
    json!({"status":"error", "code":code})
}

fn write_json(value: &Value, exit: ExitCode) -> ExitCode {
    match serde_json::to_string(value) {
        Ok(serialized) => println!("{serialized}"),
        Err(_) => println!("{{\"status\":\"error\",\"code\":\"output_error\"}}"),
    }
    exit
}
use std::{path::PathBuf, process::Command};

use serde_json::{Value, json};
use tempfile::tempdir;

fn fixture(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../fixtures")
        .join(name)
}

fn command(arguments: &[String]) -> std::process::Output {
    Command::new(env!("CARGO_BIN_EXE_wisp"))
        .args(arguments)
        .output()
        .unwrap_or_else(|error| panic!("Wisp CLI should execute: {error}"))
}

fn json_output(output: &std::process::Output) -> Value {
    serde_json::from_slice(&output.stdout)
        .unwrap_or_else(|error| panic!("CLI stdout should be JSON: {error}"))
}

#[test]
fn validate_accepts_a_valid_candidate() {
    let output = command(&[
        "artifact".to_owned(),
        "validate".to_owned(),
        fixture("spec-valid.json").display().to_string(),
    ]);
    assert!(output.status.success());
    assert_eq!(
        json_output(&output),
        json!({"artifact_type":"spec@1", "id":"SPEC-001", "status":"validated"})
    );
}

#[test]
fn validate_rejects_schema_failures_as_json_errors() {
    for fixture_name in ["spec-unknown-property.json", "spec-missing-required.json"] {
        let output = command(&[
            "artifact".to_owned(),
            "validate".to_owned(),
            fixture(fixture_name).display().to_string(),
        ]);
        assert!(!output.status.success());
        assert_eq!(
            json_output(&output),
            json!({"code":"schema_violation", "status":"error"})
        );
    }
}

#[test]
fn validate_rejects_malformed_json_as_a_json_error() {
    let output = command(&[
        "artifact".to_owned(),
        "validate".to_owned(),
        fixture("spec-malformed.json").display().to_string(),
    ]);
    assert!(!output.status.success());
    assert_eq!(
        json_output(&output),
        json!({"code":"invalid_json", "status":"error"})
    );
}

#[test]
fn persist_get_and_status_use_the_canonical_path() {
    let workspace = tempdir().unwrap_or_else(|error| panic!("temp workspace: {error}"));
    let workspace = workspace.path().display().to_string();
    let persist = command(&[
        "artifact".to_owned(),
        "persist".to_owned(),
        fixture("spec-valid.json").display().to_string(),
        "--workspace".to_owned(),
        workspace.clone(),
    ]);
    assert!(persist.status.success());
    assert_eq!(json_output(&persist)["path"], "docs/specs/SPEC-001.json");

    let get = command(&[
        "artifact".to_owned(),
        "get".to_owned(),
        "SPEC-001".to_owned(),
        "--workspace".to_owned(),
        workspace.clone(),
    ]);
    assert!(get.status.success());
    assert_eq!(
        json_output(&get)["artifact"]["spec_file_path"],
        "docs/specs/SPEC-001.json"
    );

    let status = command(&[
        "artifact".to_owned(),
        "status".to_owned(),
        "SPEC-001".to_owned(),
        "--workspace".to_owned(),
        workspace,
    ]);
    assert!(status.status.success());
    assert_eq!(json_output(&status)["status"], "uncommitted");
}

#[test]
fn status_reports_an_absent_artifact_without_failure() {
    let workspace = tempdir().unwrap_or_else(|error| panic!("temp workspace: {error}"));
    let output = command(&[
        "artifact".to_owned(),
        "status".to_owned(),
        "SPEC-404".to_owned(),
        "--workspace".to_owned(),
        workspace.path().display().to_string(),
    ]);
    assert!(output.status.success());
    assert_eq!(
        json_output(&output),
        json!({"artifact_type":"spec@1", "id":"SPEC-404", "path":"docs/specs/SPEC-404.json", "status":"absent"})
    );
}

#[test]
fn status_reports_clean_after_the_canonical_file_is_committed() {
    let workspace = tempdir().unwrap_or_else(|error| panic!("temp workspace: {error}"));
    let workspace_path = workspace.path();
    let workspace = workspace_path.display().to_string();
    let persist = command(&[
        "artifact".to_owned(),
        "persist".to_owned(),
        fixture("spec-valid.json").display().to_string(),
        "--workspace".to_owned(),
        workspace.clone(),
    ]);
    assert!(persist.status.success());

    let init = Command::new("git")
        .args(["init", "--quiet"])
        .current_dir(workspace_path)
        .status()
        .unwrap_or_else(|error| panic!("git should initialize fixture workspace: {error}"));
    assert!(init.success());
    let add = Command::new("git")
        .args(["add", "docs/specs/SPEC-001.json"])
        .current_dir(workspace_path)
        .status()
        .unwrap_or_else(|error| panic!("git should stage fixture artifact: {error}"));
    assert!(add.success());
    let commit = Command::new("git")
        .args([
            "-c",
            "user.name=Wisp Test",
            "-c",
            "user.email=wisp@example.test",
            "commit",
            "--quiet",
            "-m",
            "fixture",
        ])
        .current_dir(workspace_path)
        .status()
        .unwrap_or_else(|error| panic!("git should commit fixture artifact: {error}"));
    assert!(commit.success());

    let status = command(&[
        "artifact".to_owned(),
        "status".to_owned(),
        "SPEC-001".to_owned(),
        "--workspace".to_owned(),
        workspace,
    ]);
    assert!(status.status.success());
    assert_eq!(json_output(&status)["status"], "clean");
}
